import React, { useState } from 'react';
import {
  JxToggle,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxBadge,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: string;
}

export interface AppearanceSettingsProps {
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Обычный' },
  { value: 'display', label: 'Заголовочный' },
  { value: 'mono', label: 'Моноширинный' },
];

export default function AppearanceSettings({ onChange }: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState(100);
  const [dense, setDense] = useState(false);
  const [font, setFont] = useState('sans');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    const value: AppearanceSettingsValue = {
      theme,
      scale,
      dense,
      font,
      ...next,
    };
    onChange?.(value);
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '1.5rem',
        maxWidth: '28rem',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '0.75rem',
        }}
      >
        <h2 style={{ margin: 0, fontFamily: 'var(--jx-font-display)', color: 'var(--jx-text)' }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent">{THEME_LABELS[theme]}</JxBadge>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        <span style={{ color: 'var(--jx-text-2)', fontSize: '0.875rem' }}>Тема</span>
        <JxToggle
          items={[
            { value: 'light', label: 'Светлая' },
            { value: 'dark', label: 'Тёмная' },
            { value: 'system', label: 'Системная' },
          ]}
          value={theme}
          onValueChange={(value) => {
            const next = value as Theme;
            setTheme(next);
            emit({ theme: next });
          }}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={10}
        value={scale}
        unit="%"
        showOutput
        onValueChange={(value) => {
          setScale(value);
          emit({ scale: value });
        }}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={dense}
        onChange={(event) => {
          const next = event.target.checked;
          setDense(next);
          emit({ dense: next });
        }}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт интерфейса"
        options={FONT_OPTIONS}
        value={font}
        onValueChange={(value) => {
          setFont(value);
          emit({ font: value });
        }}
      />
    </div>
  );
}

